WITH base AS (SELECT id, channel, promo_code, starts_on, ends_on, discount_pct, CASE WHEN promo_code = 'VIP' THEN 1 ELSE 0 END is_vip, COALESCE(channel, 'UNKNOWN') resolved_channel FROM promotions WHERE ends_on > DATE '2023-09-12' AND channel IS NOT NULL) SELECT * FROM (SELECT promo_code, channel, discount_pct FROM base) src PIVOT (SUM(discount_pct) FOR channel IN ('store' AS store, 'partner' AS partner, 'mobile' AS mobile))
